      const z1 = h.baseZ * cosY + h.baseX * sinY;
      const y2 = h.baseY * cosX - z1 * sinX;
      const z2 = z1 * cosX + h.baseY * sinX;

      h.screenX = centerX + x1 * radius;
      h.screenY = centerY - y2 * radius;
      h.screenZ = z2;
