        const pulseScale = (Math.sin(h.pulse) + 1) / 2;
        const ringRadius = 4.5 + pulseScale * 10;

        // Animated Outer Radiant Ring
        ctx.strokeStyle = `rgba(0, 210, 255, ${0.9 - pulseScale * 0.8})`;
        ctx.lineWidth = 1.6;
        ctx.beginPath();
        ctx.arc(h.screenX, h.screenY, ringRadius, 0, Math.PI * 2);
        ctx.stroke();

