          ctx.font = "bold 10px monospace";
          ctx.fillStyle = isLight ? "#0f172a" : "#ffffff";
          ctx.fillText(h.code, h.screenX + 8, h.screenY - 4);

          ctx.font = "9px monospace";
          ctx.fillStyle = isLight ? "#0284c7" : "#22d3ee";
